INSERT INTO "KARANA_DESC" ("ID","KARANAID","NAME","RULER","GOODFOR","BADFOR","LANGUAGECODE") VALUES (2,1,'Кінстугхна','Марутa, Кету, хаз. 10 дому','Дії, спрямовані на покращення здоровʼя; релігійна чи духовна діяльність.','Несприятливий день для важливих справ.','uk');
INSERT INTO "KARANA_DESC" ("ID","KARANAID","NAME","RULER","GOODFOR","BADFOR","LANGUAGECODE") VALUES (3,1,'Kinstughna','Maruta, Ketu, władca 10 domu','Działania mające na celu poprawę zdrowia; czynności religijne lub duchowe.','Niekorzystny dzień na ważne sprawy.','pl');
