INSERT INTO "KARANA_DESC" ("ID","KARANAID","NAME","RULER","GOODFOR","BADFOR","LANGUAGECODE") VALUES (5,2,'Bava','Indra, Sun','Actions aimed at improving health; development, expansion, beginning new initiatives; performing religious rituals and spiritual practices.','','en');
