INSERT INTO "KARANA_DESC" ("ID","KARANAID","NAME","RULER","GOODFOR","BADFOR","LANGUAGECODE") VALUES (238,60,'Нага','Наги, Раху, господар 7-го дому','Підходить для жорстких дій, хитрості, руйнівних робіт та дій з нерухомими об’єктами.','Несприятливий день: несе імпульси, що ведуть до ворожнечі та невдач.','uk');
INSERT INTO "KARANA_DESC" ("ID","KARANAID","NAME","RULER","GOODFOR","BADFOR","LANGUAGECODE") VALUES (239,60,'Naga','Nagi, Rahu, władca 7. domu','Odpowiednia do działań twardych, podstępnych, destrukcyjnych oraz pracy z nieruchomymi obiektami.','Niekorzystny dzień: przynosi impulsy prowadzące do wrogości i niepowodzeń.','pl');
INSERT INTO "KARANA_DESC" ("ID","KARANAID","NAME","RULER","GOODFOR","BADFOR","LANGUAGECODE") VALUES (240,60,'Нага','Наги, Раху, хоз. 7 дома','Подходит для жестоких дел, хитрости, злых действий, выполнение работ с неподвижными объектами.','Неблагоприятный день для важных дел. Несет в себе импульс, ведущий к неудачам, враждебности.','ru');
