INSERT INTO "NITYAYOGA_DESC" ("ID","NITYAYOGAID","NAME","DEITY","MEANING","DESCRIPTION","LANGUAGECODE") VALUES (1,1,'Vishkumbha','Yama','Poisoned pot','Inauspicious yoga, harsh and restrictive. Favorable only for conflicts, competitions, healing and purification. Do not plan important matters.','en');
INSERT INTO "NITYAYOGA_DESC" ("ID","NITYAYOGAID","NAME","DEITY","MEANING","DESCRIPTION","LANGUAGECODE") VALUES (2,1,'Вишкумбха','Яма','Горшок с ядом','Неблагоприятная йога, жёсткая и напряжённая. Благоприятна только для конфликтов, соревнований, процедур очищения и здоровья. Не планировать важные дела.','ru');
INSERT INTO "NITYAYOGA_DESC" ("ID","NITYAYOGAID","NAME","DEITY","MEANING","DESCRIPTION","LANGUAGECODE") VALUES (3,1,'Вішкумбха','Яма','Горщик з отрутою','Несприятлива йога, жорстка та напружена. Добра лише для конфліктів, змагань, очищення й лікування. Не планувати важливі справи.','uk');
INSERT INTO "NITYAYOGA_DESC" ("ID","NITYAYOGAID","NAME","DEITY","MEANING","DESCRIPTION","LANGUAGECODE") VALUES (4,1,'Vishkumbha','Yama','Garnek z trucizną','Niekorzystna, twarda joga. Dobra tylko do konfliktów, rywalizacji i oczyszczania. Nie planować ważnych spraw.','pl');
INSERT INTO "NITYAYOGA_DESC" ("ID","NITYAYOGAID","NAME","DEITY","MEANING","DESCRIPTION","LANGUAGECODE") VALUES (5,2,'Priti','Vishnu','Joy, affection','Auspicious for meetings, communication, relationships, social events and partnerships.','en');
INSERT INTO "NITYAYOGA_DESC" ("ID","NITYAYOGAID","NAME","DEITY","MEANING","DESCRIPTION","LANGUAGECODE") VALUES (6,2,'Прити','Вишну','Возлюбленный, радость','Благоприятна для знакомств, контактов, отношений, общественных событий и брака.','ru');
INSERT INTO "NITYAYOGA_DESC" ("ID","NITYAYOGAID","NAME","DEITY","MEANING","DESCRIPTION","LANGUAGECODE") VALUES (7,2,'Пріті','Вішну','Радість, прихильність','Сприятлива для знайомств, контактів, стосунків і соціальних подій.','uk');
INSERT INTO "NITYAYOGA_DESC" ("ID","NITYAYOGAID","NAME","DEITY","MEANING","DESCRIPTION","LANGUAGECODE") VALUES (8,2,'Priti','Vishnu','Radość, uczucie','Pomyślna dla spotkań, kontaktów i relacji.','pl');
INSERT INTO "NITYAYOGA_DESC" ("ID","NITYAYOGAID","NAME","DEITY","MEANING","DESCRIPTION","LANGUAGECODE") VALUES (9,3,'Ayushman','Chandra','Longevity','Excellent for health, longevity practices, rejuvenation, legal actions and politics.','en');
