INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (9,3,'Vipat','Vipat','Risks, losses, and possible accidents. Avoid important matters today.','en');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (10,3,'Віпат','Віпат','Ризики, втрати й можливі неприємності. Уникайте важливих справ.','uk');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (11,3,'Vipat','Vipat','Ryzyko, straty i możliwe wypadki. Unikaj ważnych spraw.','pl');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (12,3,'Випат','Випат','Опасность, потери и несчастные случаи. Избегайте важных дел.','ru');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (13,4,'Kshema','Kshema','Success in your efforts. Good for progressing with plans.','en');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (14,4,'Кшема','Кшема','Успіх у ваших зусиллях. Гарно для виконання планів.','uk');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (15,4,'Kshema','Kshema','Sukces w działaniach. Dobry czas na realizację planów.','pl');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (16,4,'Кшема','Кшема','Успех в ваших усилиях. Следуйте вашим планам.','ru');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (17,5,'Pratyak','Pratyak','Obstacles may arise. Postpone important matters.','en');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (18,5,'Пратьяк','Пратьяк','Можливі перешкоди. Відкладіть важливі справи.','uk');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (19,5,'Pratyak','Pratyak','Mogą pojawić się przeszkody. Odłóż ważne sprawy.','pl');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (20,5,'Пратьяк','Пратьяк','Препятствия на пути стремлений. Отложите важные дела.','ru');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (21,6,'Sadhana','Sadhana','Favorable for achieving goals and making progress.','en');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (22,6,'Садхана','Садхана','Сприятливо для досягнення цілей і просування.','uk');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (23,6,'Sadhana','Sadhana','Sprzyja realizacji celów i postępowi.','pl');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (24,6,'Садхана','Садхана','Осуществление желаний. Назначайте на это время важные дела.','ru');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (25,7,'Naidhana','Naidhana','Possible losses or delays. Avoid expectations of quick results.','en');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (26,7,'Наїдхана','Наїдхана','Можливі втрати чи затримки. Не очікуйте швидких результатів.','uk');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (27,7,'Naidhana','Naidhana','Możliwe straty i opóźnienia. Nie oczekuj szybkich efektów.','pl');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (28,7,'Наидхана','Наидхана','Потери, несчастные случаи. Не ожидайте немедленных результатов.','ru');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (29,8,'Mitra','Mitra','Supports everyday routine tasks and simple activities.','en');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (30,8,'Мітра','Мітра','Сприяє виконанню звичайних повсякденних справ.','uk');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (31,8,'Mitra','Mitra','Sprzyja codziennym, zwykłym obowiązkom.','pl');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (32,8,'Митра','Митра','Содействует выполнению обычных дел.','ru');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (33,9,'Parama Mitra','P.Mitra','Very favorable for achieving goals and successful outcomes.','en');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (34,9,'Парама Мітра','П.Мітра','Дуже сприятлива для досягнення бажаного результату.','uk');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (35,9,'Parama Mitra','P.Mitra','Bardzo sprzyja osiąganiu celów i dobrym rezultatom.','pl');
INSERT INTO "TARABALA_DESC" ("ID","TARABALAID","NAME","SHORTNAME","DESCRIPTION","LANGUAGECODE") VALUES (36,9,'Парама Митра','П.Митра','Очень дружественна достижению желаемой цели.','ru');
