INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (1,1,'Shukla Pratipat','Pratipat','Sun, Agni','Nanda (satisfaction)','Planning; meditations; learning; travels; entering a position; holding festivals; marriage; work related to house and land; hair cutting.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (2,1,'Шукла Пратипат','Пратипат','Сонце, Агні','Нанда (задоволення)','Планування; медитації; навчання; подорожі; вступ на посаду; проведення фестивалів; шлюб; роботи, пов’язані з домом і земельною ділянкою; стрижка волосся.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (3,1,'Shukla Pratipat','Pratipat','Słońce, Agni','Nanda (zadowolenie)','Planowanie; medytacje; nauka; podróże; obejmowanie stanowiska; organizowanie festiwali; małżeństwo; prace związane z domem i działką; strzyżenie włosów.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (4,1,'Шукла Пратипат','Пратипат','Солнце, Агни','Нанда (удовлетворение)','Планирование; медитации; обучение; путешествия; вхождение в должность; проведение фестивалей; брак; работы, связанные с домом и земельным участком; подстригание волос.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (5,2,'Shukla Dwitiya','Dwitiya','Moon, Ashwini Kumara, Brahma','Bhadra (sage)','Beginning actions related to authorities; marriage; decoration with gemstones; laying a house foundation, construction; fulfilling promises; entering a position; starting new activities; treatment; travels; creativity.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (6,2,'Шукла Двітія','Двітія','Місяць, Ашвіні Кумара, Брахма','Бхадра (мудрець)','Початок дій, пов’язаних з представниками влади; шлюб; прикрашання дорогоцінним камінням; закладання фундаменту будинку, будівництво; виконання обіцянок; вступ на посаду; початок нових справ; лікування; подорожі; творчість.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (7,2,'Shukla Dwitiya','Dwitiya','Księżyc, Ashwini Kumara, Brahma','Bhadra (mędrzec)','Rozpoczynanie działań związanych z przedstawicielami władzy; małżeństwo; ozdabianie drogocennymi kamieniami; kładzenie fundamentów domu, budowa; dotrzymywanie obietnic; obejmowanie stanowiska; rozpoczynanie nowych przedsięwzięć; leczenie; podróże; twórczość.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (8,2,'Шукла Двитья','Двитья','Луна, Ашвини Кумара, Брахма','Бхадра (мудрец)','Начало действий, связанных с представителями власти; брак; украшение драгоценными камнями; закладка фундамента дома, строительство; выполнение обещаний; вхождение в должность; начало новых дел; лечение; путешествия; творчество.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (9,3,'Shukla Tritiya','Tritiya','Mars, Gauri (one of the names of Parvati)','Jaya (victory)','Beginning important activities; marriage; travels; treatment; learning; first music lesson; construction.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (10,3,'Шукла Трітія','Трітія','Марс, Гаурі (одне з імен Парваті)','Джая (перемога)','Початок важливих справ; шлюб; подорожі; лікування; навчання; перший урок музики; будівництво.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (11,3,'Shukla Tritiya','Tritiya','Mars, Gauri (jedno z imion Parvati)','Jaya (zwycięstwo)','Rozpoczynanie ważnych działań; małżeństwo; podróże; leczenie; nauka; pierwsza lekcja muzyki; budowa.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (12,3,'Шукла Тритья','Тритья','Марс, Гаури (одно из имен Парвати)','Джая (победа)','Начало важных дел; брак; путешествия; лечение; обучение; первый урок музыки; строительство.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (13,4,'Shukla Chaturthi','Chaturthi','Mercury, Ganesha','Riktha (empty hands)','Cleaning, getting rid of unnecessary things, purification (home, body, mind); disputes; fighting enemies; using weapons or fire; removing obstacles.','Unfavorable day for important matters.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (14,4,'Шукла Чатуртхи','Чатуртхи','Меркурій, Ґанеша','Риктха (порожні руки)','Прибирання, позбавлення від непотрібних речей, чистки (дому, тіла, розуму); суперечки; боротьба з ворогами; використання зброї чи вогню; усунення перешкод.','Неблагоприятный день для важных дел.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (15,4,'Shukla Chaturthi','Chaturthi','Merkury, Ganesha','Riktha (puste ręce)','Sprzątanie, pozbywanie się zbędnych rzeczy, oczyszczanie (domu, ciała, umysłu); spory; walka z wrogami; użycie broni lub ognia; usuwanie przeszkód.','Niepomyślny dzień na ważne sprawy.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (16,4,'Шукла Чатуртхи','Чатуртхи','Меркурий, Ганеша','Риктха (пустые руки)','Уборка, избавления от ненужных вещей, чистки (дома, тела, ума); споры, борьба с врагами; использование оружия, огня; устранение препятствий.','Неблагоприятный день для важных дел.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (17,5,'Shukla Panchami','Panchami','Jupiter, Naga (god of all snakes)','Purna (fullness)','Very favorable day for starting important activities; marriage; treatment; travels; learning; acquiring wealth and giving gifts.','Lending money.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (18,5,'Шукла Панчами','Панчами','Юпітер, Нага (бог усіх змій)','Пурна (повнота)','Дуже сприятливий день для початку важливих справ; шлюб; лікування; подорожі; навчання; набуття багатства й дарування подарунків.','Позичання грошей.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (19,5,'Shukla Panchami','Panchami','Jowisz, Naga (bóg wszystkich węży)','Purna (pełnia)','Bardzo pomyślny dzień na rozpoczynanie ważnych spraw; małżeństwo; leczenie; podróże; naukę; zdobywanie majątku i dawanie prezentów.','Pożyczanie pieniędzy.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (20,5,'Шукла Панчами','Панчами','Юпитер, Нага (бог всех змей)','Пурна (полнота)','Очень благоприятный день для начинания важных дел; брак; лечение; путешествия; обучение; приобретение богатства и дарение подарков.','Одалживание денег.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (21,6,'Shukla Shashthi','Shashthi','Venus, Kartikeya','Nanda (satisfaction)','Construction; matters related to houses or land; making and wearing jewelry; learning; making friendships. Marriage is moderately favorable.','Travels.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (22,6,'Шукла Шашті','Шашті','Венера, Картікея','Нанда (задоволення)','Будівництво; справи, пов’язані з будинками чи землею; виготовлення та носіння прикрас; навчання; заведення дружби. Шлюб середньо сприятливий.','Подорожі.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (23,6,'Shukla Shashthi','Shashthi','Wenus, Kartikeya','Nanda (zadowolenie)','Budowa; sprawy związane z domem lub ziemią; wykonywanie i noszenie ozdób; nauka; nawiązywanie przyjaźni. Małżeństwo umiarkowanie pomyślne.','Podróże.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (24,6,'Шукла Шашти','Шашти','Венера, Картикея','Нанда (удовлетворение)','Строительство; дела, связанные с домами или землями; изготовление и надевание украшений; обучение; заведение дружбы. Брак средне благоприятен.','Поездки.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (25,7,'Shukla Saptami','Saptami','Saturn, Surya','Bhadra (sage)','Beginning a trip; actions concerning vehicles; marriage; dancing, music; decorating with fabric or ornaments; physical exercise; treatment.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (26,7,'Шукла Саптамі','Саптамі','Сатурн, Сурʼя','Бхадра (мудрець)','Початок подорожі; дії, що стосуються транспортних засобів; шлюб; танці, музика; прикрашання тканиною чи орнаментом; фізичні вправи; лікування.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (27,7,'Shukla Saptami','Saptami','Saturn, Surya','Bhadra (mędrzec)','Rozpoczęcie podróży; czynności dotyczące pojazdów; małżeństwo; taniec, muzyka; ozdabianie tkaniną lub ornamentem; ćwiczenia fizyczne; leczenie.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (28,7,'Шукла Саптами','Саптами','Сатурн, Сурья','Бхадра (мудрец)','Начало поездки; действия, касающиеся транспортных средств; брак; танцы, музыка; украшение тканью или орнаментом; физические упражнения (тренировки); лечение.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (29,8,'Shukla Ashtami','Ashtami','Rahu, Shiva','Jaya (victory)','Physical activity, sports; matters related to houses or land; construction; studying arts; learning; meditations; rituals; healing and restorative practices.','Travels; important projects; making decisions.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (30,8,'Шукла Аштамі','Аштамі','Раху, Шіва','Джая (перемога)','Фізична активність, заняття спортом; справи, пов’язані з будинками чи землею; будівництво; вивчення мистецтв; навчання; медитації; ритуали; лікувальні та відновлювальні процедури.','Подорожі; важливі проєкти; прийняття рішень.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (31,8,'Shukla Ashtami','Ashtami','Rahu, Shiva','Jaya (zwycięstwo)','Aktywność fizyczna, sport; sprawy związane z domem lub ziemią; budowa; studiowanie sztuk; nauka; medytacje; rytuały; praktyki lecznicze i regeneracyjne.','Podróże; ważne projekty; podejmowanie decyzji.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (32,8,'Шукла Аштами','Аштами','Раху, Шива','Джая (победа)','Физическая активность, занятие спортом; дела, связанные с домами или землями; строительство; изучение искусств; обучение; медитации; ритуалы; целебные и восстановительные процедуры.','Поездки; важные проекты; принятие решений.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (33,9,'Shukla Navami','Navami','Sun, Durga','Riktha (empty hands)','Competitive actions; disputes; competition; physical exercises; working with tools; risk; meditation; rituals; recitation of mantras.','Unfavorable day for important matters. Do not start trips or travels.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (34,9,'Шукла Навамі','Навамі','Сонце, Дурґа','Риктха (порожні руки)','Змагальні дії; суперечки; конкуренція; фізичні вправи; робота з інструментами; ризик; медитації; ритуали; читання мантр.','Несприятливий день для важливих справ. Не починати поїздки та подорожі.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (35,9,'Shukla Navami','Navami','Słońce, Durga','Riktha (puste ręce)','Działania rywalizacyjne; spory; konkurencja; ćwiczenia fizyczne; praca z narzędziami; ryzyko; medytacje; rytuały; recytacja mantr.','Niepomyślny dzień na ważne sprawy. Nie rozpoczynać podróży.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (36,9,'Шукла Навами','Навами','Солнце, Дурга','Риктха (пустые руки)','Соревновательные действия; споры; конкуренция; физические упражнения (тренировки); работа с инструментами; риск; медитации; ритуалы; чтение мантр.','Неблагоприятный день для важных дел. Не начинать поездки и путешествия.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (37,10,'Shukla Dashami','Dashami','Moon, Yama','Purna (fullness)','Beginning important activities; wedding; beginning learning; wearing ornaments and new clothes; travels; matters related to vehicles, houses, and important people.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (38,10,'Шукла Дашамі','Дашамі','Місяць, Яма','Пурна (повнота)','Початок важливих справ; весілля; початок навчання; одягання прикрас і нового одягу; подорожі; справи, пов’язані з транспортом, будинками та важливими людьми.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (39,10,'Shukla Dashami','Dashami','Księżyc, Jama','Purna (pełnia)','Rozpoczynanie ważnych działań; ślub; rozpoczęcie nauki; zakładanie ozdób i nowych ubrań; podróże; sprawy związane z pojazdami, domami i ważnymi osobami.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (40,10,'Шукла Дашами','Дашами','Луна, Яма','Пурна (полнота)','Начало важных дел; свадьба; начало обучения; одевание украшений и новых одежд; путешествия; дела, связанные с транспортными средствами, домами и важными людьми.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (41,11,'Shukla Ekadashi','Ekadashi','Mars, Kubera, Vishvadeva','Nanda (satisfaction)','Fasting; limiting food; meditations; fulfilling promises; marriage; disputes; physical exercises; construction; spiritual festivals; decorating something; travels; learning.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (42,11,'Шукла Екадаші','Екадаші','Марс, Кубера, Вішвадева','Нанда (задоволення)','Піст; обмеження в їжі; медитації; виконання обіцянок; шлюб; суперечки; фізичні вправи; будівництво; духовні свята; прикрашання чогось; подорожі; навчання.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (43,11,'Shukla Ekadashi','Ekadashi','Mars, Kubera, Vishvadeva','Nanda (zadowolenie)','Post; ograniczenie jedzenia; medytacje; dotrzymywanie obietnic; małżeństwo; spory; ćwiczenia fizyczne; budowa; święta duchowe; ozdabianie czegoś; podróże; nauka.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (44,11,'Шукла Экадаши','Экадаши','Марс, Кубера, Вишвадева','Нанда (удовлетворение)','Ограничение в еде, пост; медитации; выполнение обещаний; брак; споры; физические упражнения (тренировки); строительство; духовные праздники; украшение чего-либо; поездки; обучение.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (45,12,'Shukla Dwadashi','Dwadashi','Mercury, Vishnu','Bhadra (sage)','Fulfilling promises; religious ceremonies; charity; other favorable actions. Marriage is moderately favorable.','Travels; oil massage; entering a new home.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (46,12,'Шукла Двадаші','Двадаші','Меркурій, Вішну','Бхадра (мудрець)','Виконання обіцянок; релігійні церемонії; благодійність; інші сприятливі дії. Шлюб середньо сприятливий.','Подорожі; масляний масаж; вхід до нового дому.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (47,12,'Shukla Dwadashi','Dwadashi','Merkury, Wisznu','Bhadra (mędrzec)','Dotrzymywanie obietnic; ceremonie religijne; dobroczynność; inne pomyślne działania. Małżeństwo umiarkowanie sprzyjające.','Podróże; masaż olejowy; wejście do nowego domu.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (48,12,'Шукла Двадаши','Двадаши','Меркурий, Вишну','Бхадра (мудрец)','Выполнение обещаний; религиозные церемонии; благотворительность; другие благоприятные действия. Брак средне благоприятен.','Путешествия; масляный массаж; вход в новый дом.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (49,13,'Shukla Trayodashi','Trayodashi','Jupiter, Kamadeva','Jaya (victory)','Beginning important activities; wearing new clothes or jewelry; fighting; fulfilling promises; treatment; travels.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (50,13,'Шукла Трайодаші','Трайодаші','Юпітер, Камадева','Джая (перемога)','Початок важливих справ; одягання нового одягу чи прикрас; боротьба; виконання обіцянок; лікування; подорожі.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (51,13,'Shukla Trayodashi','Trayodashi','Jowisz, Kamadeva','Jaya (zwycięstwo)','Rozpoczynanie ważnych działań; zakładanie nowej odzieży lub ozdób; walka; dotrzymywanie obietnic; leczenie; podróże.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (52,13,'Шукла Трайодаши','Трайодаши','Юпитер, Камадева','Джая (победа)','Начало важных дел; одевание новой одежды и украшений; борьба; выполнение обещаний; лечение; поездки.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (53,14,'Shukla Chaturdashi','Chaturdashi','Venus, Shiva, Rudra','Riktha (empty hands)','Meditations, reading sacred books or mantras.','Unfavorable day for important matters. Avoid travel and hair cutting.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (54,14,'Шукла Чатурдаші','Чатурдаші','Венера, Шіва, Рудра','Риктха (порожні руки)','Медитації, читання священних книг чи мантр.','Несприятливий день для важливих справ. Уникати подорожей і стрижки волосся.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (55,14,'Shukla Chaturdashi','Chaturdashi','Wenus, Shiva, Rudra','Riktha (puste ręce)','Medytacje, czytanie świętych ksiąg lub mantr.','Niepomyślny dzień na ważne sprawy. Unikać podróży oraz strzyżenia włosów.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (56,14,'Шукла Чатурдаши','Чатурдаши','Венера, Шива, Рудра','Риктха (пустые руки)','Медитации, чтение священных книг, мантр.','Неблагоприятный день для важных дел. Избегать путешествий и подстригания волос.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (57,15,'Purnima (Full Moon)','Purnima','Saturn, Chandra (Soma)/Pitri','Purna (fullness)','Beginning important activities; construction; entering a position; beginning work; household activities; physical activity; spiritual ceremonies; fasting; meditations.','Travels; oil massage; surgical operations.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (58,15,'Пурніма (Повня)','Пурніма','Сатурн, Чандра (Сома)/Пітрі','Пурна (повнота)','Початок важливих справ; будівництво; вступ на посаду; початок роботи; домашні справи; фізична активність; духовні церемонії; піст; медитації.','Подорожі; масляний масаж; хірургічні операції.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (59,15,'Purnima (Pełnia)','Purnima','Saturn, Chandra (Soma)/Pitri','Purna (pełnia)','Rozpoczynanie ważnych działań; budowa; obejmowanie stanowiska; rozpoczęcie pracy; prace domowe; aktywność fizyczna; ceremonie duchowe; post; medytacje.','Podróże; masaż olejowy; operacje chirurgiczne.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (60,15,'Пурнима (Полнолуние)','Пурнима','Сатурн, Чандра (Сома)/Питри','Пурна (полнота)','Начало важных дел; строительство; вхождение в должность; начало работы; домашние дела; физическая активность; духовные церемонии; пост; медитации.','Поездки; масляный массаж; хирургические операции.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (61,16,'Krishna Pratipat','Pratipat','Sun, Agni','Nanda (satisfaction)','Beginning important activities; learning; festivals; travels; entering a position; marriage; matters related to houses or land; hair cutting.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (62,16,'Крішна Пратипат','Пратипат','Сонце, Агні','Нанда (задоволення)','Початок важливих справ; навчання; фестивалі; подорожі; вступ на посаду; шлюб; справи, повʼязані з будинками чи землею; стрижка волосся.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (63,16,'Krishna Pratipat','Pratipat','Słońce, Agni','Nanda (zadowolenie)','Rozpoczynanie ważnych działań; nauka; festiwale; podróże; obejmowanie stanowiska; małżeństwo; sprawy dotyczące domu lub ziemi; strzyżenie włosów.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (64,16,'Кришна Пратипат','Пратипат','Солнце, Агни','Нанда (удовлетворение)','Начало важных дел; обучение; фестивали; путешествия; вхождение в должность; брак; дела, связанные с домами или землями; подстригание волос.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (65,17,'Krishna Dwitiya','Dwitiya','Moon, Ashwini Kumara, Brahma','Bhadra (sage)','Beginning new activities; forming new goals; actions related to authorities; marriage; decoration with gemstones; laying a house foundation; construction; fulfilling promises; entering a position; beginning work; treatment.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (66,17,'Крішна Двітія','Двітія','Місяць, Ашвіні Кумара, Брахма','Бхадра (мудрець)','Початок нових справ; формування нових цілей; дії, повʼязані з представниками влади; шлюб; прикрашання дорогоцінним камінням; закладання фундаменту будинку; будівництво; виконання обіцянок; вступ на посаду; початок роботи; лікування.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (67,17,'Krishna Dwitiya','Dwitiya','Księżyc, Ashwini Kumara, Brahma','Bhadra (mędrzec)','Rozpoczynanie nowych przedsięwzięć; formułowanie nowych celów; działania związane z przedstawicielami władzy; małżeństwo; ozdabianie kamieniami szlachetnymi; kładzenie fundamentów domu; budowa; dotrzymywanie obietnic; obejmowanie stanowiska; rozpoczęcie pracy; leczenie.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (68,17,'Кришна Двитья','Двитья','Луна, Ашвини Кумара, Брахма','Бхадра (мудрец)','Начало новых дел; формировании новых целей;  действия, связанные с представителями власти; брак; украшение драгоценными камнями; закладка фундамента дома, строительство; выполнение обещаний; вхождение в должность; начало работы; лечение;','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (69,18,'Krishna Tritiya','Tritiya','Mars, Gauri (one of the names of Parvati)','Jaya (victory)','Beginning important activities; marriage; travels; treatment; learning; first music lesson; construction.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (70,18,'Крішна Трітія','Трітія','Марс, Гаурі (одне з імен Парваті)','Джая (перемога)','Початок важливих справ; шлюб; подорожі; лікування; навчання; перший урок музики; будівництво.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (71,18,'Krishna Tritiya','Tritiya','Mars, Gauri (jedno z imion Parvati)','Jaya (zwycięstwo)','Rozpoczynanie ważnych działań; małżeństwo; podróże; leczenie; nauka; pierwsza lekcja muzyki; budowa.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (72,18,'Кришна Тритья','Тритья','Марс, Гаури (одно из имен Парвати)','Джая (победа)','Начало важных дел; брак; путешествия; лечение; обучение; первый урок музыки; строительство.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (73,19,'Krishna Chaturthi','Chaturthi','Mercury, Ganesha','Riktha (empty hands)','Cleaning, decluttering, purification (home, body, mind); disputes; fighting enemies; using weapons or fire; removing obstacles.','Unfavorable day for important matters.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (74,19,'Крішна Чатуртгі','Чатуртгі','Меркурій, Ґанеша','Риктха (порожні руки)','Прибирання, позбавлення від непотрібних речей, очищення (дому, тіла, розуму); суперечки; боротьба з ворогами; використання зброї чи вогню; усунення перешкод.','Несприятливий день для важливих справ.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (75,19,'Krishna Chaturthi','Chaturthi','Merkury, Ganesha','Riktha (puste ręce)','Sprzątanie, pozbywanie się zbędnych rzeczy, oczyszczanie (domu, ciała, umysłu); spory; walka z wrogami; użycie broni lub ognia; usuwanie przeszkód.','Niepomyślny dzień na ważne sprawy.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (76,19,'Кришна Чатуртхи','Чатуртхи','Меркурий, Ганеша','Риктха (пустые руки)','Уборка, избавления от ненужных вещей, чистки (дома, тела, ума); споры, борьба с врагами; использование оружия, огня; устранение препятствий.','Неблагоприятный день для важных дел.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (77,20,'Krishna Panchami','Panchami','Jupiter, Naga (god of all snakes)','Purna (fullness)','Very favorable day for starting important activities; marriage; treatment; travels; learning; acquiring wealth and giving gifts.','Lending money.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (78,20,'Крішна Панчамі','Панчамі','Юпітер, Нага (бог усіх змій)','Пурна (повнота)','Дуже сприятливий день для початку важливих справ; шлюб; лікування; подорожі; навчання; набуття багатства й дарування подарунків.','Позичання грошей.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (79,20,'Krishna Panchami','Panchami','Jowisz, Naga (bóg wszystkich węży)','Purna (pełnia)','Bardzo pomyślny dzień na rozpoczynanie ważnych spraw; małżeństwo; leczenie; podróże; nauka; zdobywanie majątku i dawanie prezentów.','Pożyczanie pieniędzy.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (80,20,'Кришна Панчами','Панчами','Юпитер, Нага (бог всех змей)','Пурна (полнота)','Очень благоприятный день для начинания важных дел; брак; лечение; путешествия; обучение; приобретение богатства и дарение подарков.','Одалживание денег.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (81,21,'Krishna Shashthi','Shashthi','Venus, Kartikeya','Nanda (satisfaction)','Construction; matters related to houses or land; making and wearing jewelry; learning; making friendships. Marriage is moderately favorable.','Travels.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (82,21,'Крішна Шашті','Шашті','Венера, Картікея','Нанда (задоволення)','Будівництво; справи, пов’язані з будинками чи землею; виготовлення та носіння прикрас; навчання; заведення дружби. Шлюб середньо сприятливий.','Подорожі.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (83,21,'Krishna Shashthi','Shashthi','Wenus, Kartikeya','Nanda (zadowolenie)','Budowa; sprawy związane z domem lub ziemią; wykonywanie i noszenie ozdób; nauka; nawiązywanie przyjaźni. Małżeństwo umiarkowanie pomyślne.','Podróże.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (84,21,'Кришна Шашти','Шашти','Венера, Картикея','Нанда (удовлетворение)','Строительство; дела, связанные с домами или землями; изготовление и надевание украшений; обучение; заведение дружбы. Брак средне благоприятен.','Поездки.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (85,22,'Krishna Saptami','Saptami','Saturn, Surya','Bhadra (sage)','Beginning a trip; actions concerning vehicles; marriage; dancing, music; decorating with fabric or ornaments; physical exercises; treatment.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (86,22,'Крішна Саптамі','Саптамі','Сатурн, Сурʼя','Бхадра (мудрець)','Початок подорожі; дії, що стосуються транспортних засобів; шлюб; танці, музика; прикрашання тканиною чи орнаментом; фізичні вправи; лікування.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (87,22,'Krishna Saptami','Saptami','Saturn, Surya','Bhadra (mędrzec)','Rozpoczęcie podróży; czynności dotyczące pojazdów; małżeństwo; taniec, muzyka; ozdabianie tkaniną lub ornamentem; ćwiczenia fizyczne; leczenie.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (88,22,'Кришна Саптами','Саптами','Сатурн, Сурья','Бхадра (мудрец)','Начало поездки; действия, касающиеся транспортных средств; брак; танцы, музыка; украшение тканью или орнаментом; физические упражнения (тренировки); лечение.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (89,23,'Krishna Ashtami','Ashtami','Rahu, Shiva','Jaya (victory)','Physical activity; sports; matters related to houses or land; construction; studying arts; learning; meditations; rituals; healing and restorative practices.','Travels; important projects; making decisions.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (90,23,'Крішна Аштамі','Аштамі','Раху, Шіва','Джая (перемога)','Фізична активність, заняття спортом; справи, пов’язані з будинками чи землею; будівництво; вивчення мистецтв; навчання; медитації; ритуали; лікувальні та відновлювальні процедури.','Подорожі; важливі проєкти; прийняття рішень.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (91,23,'Krishna Ashtami','Ashtami','Rahu, Shiva','Jaya (zwycięstwo)','Aktywność fizyczna, sport; sprawy związane z domem lub ziemią; budowa; studiowanie sztuk; nauka; medytacje; rytuały; praktyki lecznicze i regeneracyjne.','Podróże; ważne projekty; podejmowanie decyzji.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (92,23,'Кришна Аштами','Аштами','Раху, Шива','Джая (победа)','Физическая активность, занятие спортом; дела, связанные с домами или землями; строительство; изучение искусств; обучение; медитации; ритуалы; целебные и восстановительные процедуры.','Поездки; важные проекты; принятие решений.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (93,24,'Krishna Navami','Navami','Sun, Durga','Riktha (empty hands)','Competitive actions; disputes; competition; physical exercises; working with tools; risk; meditations; rituals; recitation of mantras.','Unfavorable day for important matters. Do not start trips or travels.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (94,24,'Крішна Навамі','Навамі','Сонце, Дурґа','Риктха (порожні руки)','Змагальні дії; суперечки; конкуренція; фізичні вправи; робота з інструментами; ризик; медитації; ритуали; читання мантр.','Несприятливий день для важливих справ. Не починати поїздки та подорожі.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (95,24,'Krishna Navami','Navami','Słońce, Durga','Riktha (puste ręce)','Działania rywalizacyjne; spory; konkurencja; ćwiczenia fizyczne; praca z narzędziami; ryzyko; medytacje; rytuały; recytacja mantr.','Niepomyślny dzień na ważne sprawy. Nie rozpoczynać podróży.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (96,24,'Кришна Навами','Навами','Солнце, Дурга','Риктха (пустые руки)','Соревновательные действия; споры; конкуренция; физические упражнения (тренировки); работа с инструментами; риск; медитации; ритуалы; чтение мантр.','Неблагоприятный день для важных дел. Не начинать поездки и путешествия.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (97,25,'Krishna Dashami','Dashami','Moon, Yama','Purna (fullness)','Beginning important activities; wedding; beginning learning; wearing ornaments and new clothes; travels; matters related to vehicles, houses, important people; healing procedures; oil massage.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (98,25,'Крішна Дашамі','Дашамі','Місяць, Яма','Пурна (повнота)','Початок важливих справ; весілля; початок навчання; одягання прикрас і нового одягу; подорожі; справи, пов’язані з транспортом, будинками та важливими людьми; лікувальні процедури; масляний масаж.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (99,25,'Krishna Dashami','Dashami','Księżyc, Jama','Purna (pełnia)','Rozpoczynanie ważnych działań; ślub; rozpoczęcie nauki; zakładanie ozdób i nowych ubrań; podróże; sprawy dotyczące pojazdów, domów i ważnych osób; zabiegi lecznicze; masaż olejowy.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (100,25,'Кришна Дашами','Дашами','Луна, Яма','Пурна (полнота)','Начало важных дел; свадьба; начало обучения; одевание украшений и новых одежд; путешествия; дела, связанные с транспортными средствами, домами и важными людьми; целебные процедуры; масляный массаж.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (101,26,'Krishna Ekadashi','Ekadashi','Mars, Kubera, Vishvadeva','Nanda (satisfaction)','Fasting; limiting food; meditations; fulfilling promises; marriage; disputes; physical exercises; construction; spiritual festivals; decorating something; travels; learning.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (102,26,'Крішна Екадаші','Екадаші','Марс, Кубера, Вішвадева','Нанда (задоволення)','Піст; обмеження в їжі; медитації; виконання обіцянь; шлюб; суперечки; фізичні вправи; будівництво; духовні свята; прикрашання чогось; подорожі; навчання.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (103,26,'Krishna Ekadashi','Ekadashi','Mars, Kubera, Vishvadeva','Nanda (zadowolenie)','Post; ograniczenie jedzenia; medytacje; dotrzymywanie obietnic; małżeństwo; spory; ćwiczenia fizyczne; budowa; święta duchowe; ozdabianie czegoś; podróże; nauka.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (104,26,'Кришна Экадаши','Экадаши','Марс, Кубера, Вишвадева','Нанда (удовлетворение)','Ограничение в еде, пост; медитации; выполнение обещаний; брак; споры; физические упражнения (тренировки); строительство; духовные праздники; украшение чего-либо; поездки; обучение.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (105,27,'Krishna Dwadashi','Dwadashi','Mercury, Vishnu','Bhadra (sage)','Fulfilling promises; religious ceremonies; charity; other favorable actions. Marriage is moderately favorable.','Travels; oil massage; entering a new home.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (106,27,'Крішна Двадаші','Двадаші','Меркурій, Вішну','Бхадра (мудрець)','Виконання обіцянок; релігійні церемонії; благодійність; інші сприятливі дії. Шлюб середньо сприятливий.','Подорожі; масляний масаж; вхід до нового дому.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (107,27,'Krishna Dwadashi','Dwadashi','Merkury, Wisznu','Bhadra (mędrzec)','Dotrzymywanie obietnic; ceremonie religijne; dobroczynność; inne pomyślne działania. Małżeństwo umiarkowanie sprzyjające.','Podróże; masaż olejowy; wejście do nowego domu.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (108,27,'Кришна Двадаши','Двадаши','Меркурий, Вишну','Бхадра (мудрец)','Выполнение обещаний; религиозные церемонии; благотворительность; другие благоприятные действия. Брак средне благоприятен.','Путешествия; масляный массаж; вход в новый дом.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (109,28,'Krishna Trayodashi','Trayodashi','Jupiter, Kamadeva','Jaya (victory)','Beginning important activities; wearing new clothes or jewelry; fighting; fulfilling promises; treatment; travels.','','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (110,28,'Крішна Трайодаші','Трайодаші','Юпітер, Камадева','Джая (перемога)','Початок важливих справ; одягання нового одягу чи прикрас; боротьба; виконання обіцянок; лікування; подорожі.','','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (111,28,'Krishna Trayodashi','Trayodashi','Jowisz, Kamadeva','Jaya (zwycięstwo)','Rozpoczynanie ważnych działań; zakładanie nowej odzieży lub ozdób; walka; dotrzymywanie obietnic; leczenie; podróże.','','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (112,28,'Кришна Трайодаши','Трайодаши','Юпитер, Камадева','Джая (победа)','Начало важных дел; одевание новой одежды и украшений; борьба; выполнение обещаний; лечение; поездки.','','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (113,29,'Krishna Chaturdashi','Chaturdashi','Venus, Shiva, Rudra','Riktha (empty hands)','Meditations; reading sacred books; chanting mantras.','Unfavorable day for important matters. Avoid travel and hair cutting.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (114,29,'Крішна Чатурдаші','Чатурдаші','Венера, Шіва, Рудра','Риктха (порожні руки)','Медитації; читання священних книг; мантри.','Несприятливий день для важливих справ. Уникати подорожей і стрижки волосся.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (115,29,'Krishna Chaturdashi','Chaturdashi','Wenus, Shiva, Rudra','Riktha (puste ręce)','Medytacje; czytanie świętych ksiąg; mantry.','Niepomyślny dzień na ważne sprawy. Unikać podróży i strzyżenia włosów.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (116,29,'Кришна Чатурдаши','Чатурдаши','Венера, Шива, Рудра','Риктха (пустые руки)','Медитации, чтение священных книг, мантр.','Неблагоприятный день для важных дел. Избегать путешествий и подстригания волос.','ru');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (117,30,'Amavasya (New Moon)','Amavasya','Rahu, Chandra (Soma)/Pitri','Purna (fullness)','Spiritual practices; meditation; religious rituals; matters connected with honoring deceased ancestors; work with lineage; austerities.','Unfavorable day for almost any activities.','en');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (118,30,'Амавасья (Молодик)','Амавасья','Раху, Чандра (Сома)/Пітрі','Пурна (повнота)','Духовні практики; медитації; релігійні ритуали; справи, пов’язані з вшануванням померлих предків; робота з родом; аскези.','Несприятливий день майже для будь-яких справ.','uk');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (119,30,'Amavasya (Nów)','Amavasya','Rahu, Chandra (Soma)/Pitri','Purna (pełnia)','Praktyki duchowe; medytacje; rytuały religijne; działania związane z czczeniem zmarłych przodków; praca z rodem; ascezy.','Niepomyślny dzień prawie dla wszystkich działań.','pl');
INSERT INTO "TITHI_DESC" ("ID","TITHIID","NAME","SHORTNAME","RULER","TYPE","GOODFOR","BADFOR","LANGUAGECODE") VALUES (120,30,'Амавасья (Новолуние)','Амавасья','Раху, Чандра (Сома)/Питри','Пурна (полнота)','Духовные практики; медитации; религиозные ритуалы; дела, связанные с почитанием умерших предков; работа с родом, аскезы.','Неблагоприятный день почти для любых дел.','ru');
