INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (1,1,'Reduced income, discomfort, possible relocations, fatigue and poor health.','en');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (2,1,'Зменшення доходів, дискомфорт, можливі переїзди, втома та погане самопочуття.','uk');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (3,1,'Spadek dochodów, dyskomfort, możliwe przeprowadzki, zmęczenie i gorsze zdrowie.','pl');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (4,1,'Сокращение доходов, дискомфорт, возможны перемещения с места на место, усталость и плохое здоровье','ru');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (5,2,'Rising expenses (possibly incomes too), eye issues, confusion.','en');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (6,2,'Зростання витрат (можливо, й доходів), проблеми з очима, омани.','uk');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (7,2,'Wzrost wydatków (może także dochodów), problemy z oczami, złudzenia.','pl');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (8,2,'Возрастание расходов, но, возможно, и доходов тоже, болезни глаз, заблуждения','ru');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (9,3,'Success, relief from illness, overcoming obstacles, more energy.','en');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (10,3,'Успіх, полегшення від хвороб, подолання перешкод, більше енергії.','uk');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (11,3,'Sukces, ulga od chorób, pokonywanie przeszkód, więcej energii.','pl');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (12,3,'Успех, свобода от болезней, преодоление преград, возрастание энергии','ru');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (13,4,'Relationship issues, loss of reputation, general malaise, stomach problems.','en');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (14,4,'Проблеми у стосунках, втрата репутації, загальне нездужання, проблеми зі шлунком.','uk');
