INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (16,4,'Проблемы во взаимоотношениях, бесчестие, общее недомогание, в частности, с желудком','ru');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (17,5,'Sadness, confrontation, poor judgment, physical discomfort.','en');
INSERT INTO "TRANSIT_DESC" ("ID","TRANSITID","DESCRIPTION","LANGUAGECODE") VALUES (18,5,'Смуток, протистояння, слабке судження, фізичний дискомфорт.','uk');
