BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "APPSETTING" (
	"ID"	INTEGER,
	"GROUPCODE"	TEXT,
	"SETTINGCODE"	TEXT,
	"ACTIVE"	SMALLINT,
	PRIMARY KEY("ID" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "APP_META" (
	"KEY"	TEXT,
	"VALUE"	TEXT,
	PRIMARY KEY("KEY")
);
CREATE TABLE IF NOT EXISTS "APP_TEXTS" (
	"ID"	INTEGER,
	"NATIVETEXT"	TEXT,
	"FOREIGNTEXT"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "COLOR" (
	"ID"	INTEGER,
	"CODE"	TEXT,
	"ARGBVALUE"	INTEGER,
	PRIMARY KEY("ID" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "COLOR_DESC" (
	"ID"	INTEGER,
	"COLORID"	INTEGER,
	"NAME"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("COLORID") REFERENCES "COLOR"("ID")
);
CREATE TABLE IF NOT EXISTS "DVLINENAME" (
	"ID"	INTEGER,
	"CODE"	TEXT,
	PRIMARY KEY("ID" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "DVLINENAME_DESC" (
	"ID"	INTEGER,
	"DVLINENAMEID"	INTEGER,
	"SHORTNAME"	TEXT,
	"NAME"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("DVLINENAMEID") REFERENCES "DVLINENAME"("ID")
);
CREATE TABLE IF NOT EXISTS "ECLIPSE" (
	"ID"	INTEGER,
	"ECLIPSECODE"	VARCHAR(10),
	PRIMARY KEY("ID" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "ECLIPSE_DESC" (
	"ID"	INTEGER,
	"ECLIPSEID"	INTEGER,
	"NAME"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("ECLIPSEID") REFERENCES "ECLIPSE"("ID")
);
CREATE TABLE IF NOT EXISTS "GHATI60" (
	"ID"	INTEGER,
	"POSITION"	SMALLINT,
	"COLORID"	INTEGER,
	"GHATI60CODE"	TEXT,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("COLORID") REFERENCES "COLOR"("ID")
);
CREATE TABLE IF NOT EXISTS "GHATI60_DESC" (
	"ID"	INTEGER,
	"GHATI60ID"	INTEGER,
	"SHORTNAME"	TEXT,
	"NAME"	TEXT,
	"DESCRIPTION"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("GHATI60ID") REFERENCES "GHATI60"("ID")
);
CREATE TABLE IF NOT EXISTS "KARANA" (
	"ID"	INTEGER,
	"TITHIID"	INTEGER,
	"POSITION"	SMALLINT,
	"COLORID"	INTEGER,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("COLORID") REFERENCES "COLOR"("ID"),
	FOREIGN KEY("TITHIID") REFERENCES "TITHI"("ID")
);
CREATE TABLE IF NOT EXISTS "KARANA_DESC" (
	"ID"	INTEGER,
	"KARANAID"	INTEGER,
	"NAME"	TEXT,
	"RULER"	TEXT,
	"GOODFOR"	TEXT,
	"BADFOR"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("KARANAID") REFERENCES "KARANA"("ID")
);
CREATE TABLE IF NOT EXISTS "LANGUAGE" (
	"ID"	INTEGER,
	"LANGUAGECODE"	VARCHAR(2),
	"CULTURECODE"	VARCHAR(5),
	PRIMARY KEY("ID" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "LOCATION" (
	"ID"	INTEGER,
	"LOCALITY"	TEXT,
	"LATITUDE"	TEXT,
	"LONGITUDE"	TEXT,
	"REGION"	TEXT,
	"STATE"	TEXT,
	"COUNTRY"	TEXT,
	"COUNTRYCODE"	VARCHAR(2),
	"LANGUAGECODE"	VARCHAR(2),
	"LOCALITY_NORM"	TEXT,
	"REGION_NORM"	TEXT,
	"STATE_NORM"	TEXT,
	"COUNTRY_NORM"	TEXT,
	PRIMARY KEY("ID" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "MASA" (
	"ID"	INTEGER,
	"ZODIACID"	INTEGER,
	"SHUNYANAKSHATRA"	TEXT,
	"SHUNYATITHI"	TEXT,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("ZODIACID") REFERENCES "ZODIAC"("ID")
);
CREATE TABLE IF NOT EXISTS "MASA_DESC" (
	"ID"	INTEGER,
	"MASAID"	INTEGER,
	"NAME"	TEXT,
	"LANGUAGECODE"	TEXT,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("MASAID") REFERENCES "MASA"("ID")
);
CREATE TABLE IF NOT EXISTS "MRITYUBHAGA" (
	"ID"	INTEGER,
	"PLANETID"	INTEGER,
	"ZODIACID"	INTEGER,
	"DEGREE"	INTEGER,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("PLANETID") REFERENCES "PLANET"("ID"),
	FOREIGN KEY("ZODIACID") REFERENCES "ZODIAC"("ID")
);
CREATE TABLE IF NOT EXISTS "MUHURTA" (
	"ID"	INTEGER,
	"COLORID"	INTEGER,
	"MUHURTACODE"	TEXT,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("COLORID") REFERENCES "COLOR"("ID")
);
CREATE TABLE IF NOT EXISTS "MUHURTA30" (
	"ID"	INTEGER,
	"COLORID"	INTEGER,
	"MUHURTA30CODE"	TEXT,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("COLORID") REFERENCES "COLOR"("ID")
);
CREATE TABLE IF NOT EXISTS "MUHURTA30_DESC" (
	"ID"	INTEGER,
	"MUHURTA30ID"	INTEGER,
	"SHORTNAME"	TEXT,
	"NAME"	TEXT,
	"DESCRIPTION"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("MUHURTA30ID") REFERENCES "MUHURTA30"("ID")
);
CREATE TABLE IF NOT EXISTS "MUHURTA_DESC" (
	"ID"	INTEGER,
	"MUHURTAID"	INTEGER,
	"NAME"	TEXT,
	"SHORTNAME"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("MUHURTAID") REFERENCES "MUHURTA"("ID")
);
CREATE TABLE IF NOT EXISTS "NAKSHATRA" (
	"ID"	INTEGER,
	"NAKSHATRACODE"	TEXT,
	"COLORID"	INTEGER,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("COLORID") REFERENCES "COLOR"("ID")
);
CREATE TABLE IF NOT EXISTS "NAKSHATRA_DESC" (
	"ID"	INTEGER,
	"NAKSHATRAID"	INTEGER,
	"NAME"	TEXT,
	"SHORTNAME"	TEXT,
	"RULER"	TEXT,
	"NATURE"	TEXT,
	"DESCRIPTION"	TEXT,
	"GOODFOR"	TEXT,
	"BADFOR"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("NAKSHATRAID") REFERENCES "NAKSHATRA"("ID")
);
CREATE TABLE IF NOT EXISTS "NITYAYOGA" (
	"ID"	INTEGER,
	"NYCODE"	TEXT,
	"COLORID"	INTEGER,
	"NAKSHATRAID"	INTEGER,
	"YOGIPLANETID"	INTEGER,
	"AVAYOGIPLANETID"	INTEGER,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("AVAYOGIPLANETID") REFERENCES "PLANET"("ID"),
	FOREIGN KEY("COLORID") REFERENCES "COLOR"("ID"),
	FOREIGN KEY("NAKSHATRAID") REFERENCES "NAKSHATRA"("ID"),
	FOREIGN KEY("YOGIPLANETID") REFERENCES "PLANET"("ID")
);
CREATE TABLE IF NOT EXISTS "NITYAYOGA_DESC" (
	"ID"	INTEGER,
	"NITYAYOGAID"	INTEGER,
	"NAME"	TEXT,
	"DEITY"	TEXT,
	"MEANING"	TEXT,
	"DESCRIPTION"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("NITYAYOGAID") REFERENCES "NITYAYOGA"("ID")
);
CREATE TABLE IF NOT EXISTS "PADA" (
	"ID"	INTEGER,
	"ZODIACID"	INTEGER,
	"NAKSHATRAID"	INTEGER,
	"PADANUMBER"	INTEGER,
	"DREKKANA"	INTEGER,
	"SPECIALNAVAMSA"	TEXT,
	"NAVAMSA"	INTEGER,
	"COLORID"	INTEGER,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("COLORID") REFERENCES "COLOR"("ID"),
	FOREIGN KEY("NAKSHATRAID") REFERENCES "NAKSHATRA"("ID"),
	FOREIGN KEY("ZODIACID") REFERENCES "ZODIAC"("ID")
);
CREATE TABLE IF NOT EXISTS "PLANET" (
	"ID"	INTEGER,
	"PLANETCODE"	TEXT,
	PRIMARY KEY("ID" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "PLANET_DESC" (
	"ID"	INTEGER,
	"PLANETID"	INTEGER,
	"NAME"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("PLANETID") REFERENCES "PLANET"("ID")
);
CREATE TABLE IF NOT EXISTS "PROFILE" (
	"ID"	INTEGER,
	"PROFILENAME"	TEXT,
	"PERSONNAME"	TEXT,
	"PERSONSURNAME"	TEXT,
	"DATEOFBIRTH"	TEXT,
	"PLACEOFBIRTHID"	INTEGER,
	"PLACEOFLIVINGID"	INTEGER,
	"MESSAGE"	TEXT,
	"CHECKED"	INTEGER,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("PLACEOFBIRTHID") REFERENCES "LOCATION"("ID"),
	FOREIGN KEY("PLACEOFLIVINGID") REFERENCES "LOCATION"("ID")
);
CREATE TABLE IF NOT EXISTS "SPECIALNAVAMSA_DESC" (
	"ID"	INTEGER,
	"SPECIALNAVAMSAID"	INTEGER,
	"NAME"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "TARABALA" (
	"ID"	INTEGER,
	"COLORID"	INTEGER,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("COLORID") REFERENCES "COLOR"("ID")
);
CREATE TABLE IF NOT EXISTS "TARABALA_DESC" (
	"ID"	INTEGER,
	"TARABALAID"	INTEGER,
	"NAME"	TEXT,
	"SHORTNAME"	TEXT,
	"DESCRIPTION"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("TARABALAID") REFERENCES "TARABALA"("ID")
);
CREATE TABLE IF NOT EXISTS "TITHI" (
	"ID"	INTEGER,
	"COLORID"	INTEGER,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("COLORID") REFERENCES "COLOR"("ID")
);
CREATE TABLE IF NOT EXISTS "TITHI_DESC" (
	"ID"	INTEGER,
	"TITHIID"	INTEGER,
	"NAME"	TEXT,
	"SHORTNAME"	TEXT,
	"RULER"	TEXT,
	"TYPE"	TEXT,
	"GOODFOR"	TEXT,
	"BADFOR"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("TITHIID") REFERENCES "TITHI"("ID")
);
CREATE TABLE IF NOT EXISTS "TRANSIT" (
	"ID"	INTEGER,
	"PLANETID"	INTEGER,
	"HOUSE"	INTEGER,
	"COLORID"	INTEGER,
	"VEDHA"	TEXT,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("COLORID") REFERENCES "COLOR"("ID"),
	FOREIGN KEY("PLANETID") REFERENCES "PLANET"("ID")
);
CREATE TABLE IF NOT EXISTS "TRANSIT_DESC" (
	"ID"	INTEGER,
	"TRANSITID"	INTEGER,
	"DESCRIPTION"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("TRANSITID") REFERENCES "TRANSIT"("ID")
);
CREATE TABLE IF NOT EXISTS "TRANSIT_EVENTS" (
	"ID"	INTEGER,
	"PROFILEID"	INTEGER,
	"EVENTDATE"	VARCHAR(20),
	"LOCATIONID"	INTEGER,
	"EVENTNAME"	TEXT,
	"DESCRIPTION"	TEXT,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("LOCATIONID") REFERENCES "LOCATION"("ID"),
	FOREIGN KEY("PROFILEID") REFERENCES "PROFILE"("ID")
);
CREATE TABLE IF NOT EXISTS "USER_EVENTS" (
	"ID"	INTEGER,
	"PROFILEID"	INTEGER,
	"DATESTART"	TEXT,
	"DATEEND"	TEXT,
	"NAME"	TEXT,
	"MESSAGE"	TEXT,
	"ARGBVALUE"	INTEGER,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("PROFILEID") REFERENCES "PROFILE"("ID")
);
CREATE TABLE IF NOT EXISTS "YOGA" (
	"ID"	INTEGER,
	"COLORID"	INTEGER,
	"YOGACODE"	TEXT,
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("COLORID") REFERENCES "COLOR"("ID")
);
CREATE TABLE IF NOT EXISTS "YOGA_DESC" (
	"ID"	INTEGER,
	"YOGAID"	INTEGER,
	"NAME"	TEXT,
	"SHORTNAME"	VARCHAR(3),
	"DESCRIPTION"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("YOGAID") REFERENCES "YOGA"("ID")
);
CREATE TABLE IF NOT EXISTS "ZODIAC" (
	"ID"	INTEGER,
	"ZODIACCODE"	VARCHAR(3),
	PRIMARY KEY("ID" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "ZODIAC_DESC" (
	"ID"	INTEGER,
	"ZODIACID"	INTEGER,
	"NAME"	TEXT,
	"LANGUAGECODE"	VARCHAR(2),
	PRIMARY KEY("ID" AUTOINCREMENT),
	FOREIGN KEY("ZODIACID") REFERENCES "ZODIAC"("ID")
);
COMMIT;
